import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardMedia,
  CardContent,
  Typography,
  Button,
  Stack,
  useTheme
} from '@mui/material';

type Product = {
  id: string;
  name: string;
  image: string;
  price: number;
  description?: string;
};

type Props = {

};


const ProductCatalog: React.FC<Props> = () => {
    const [product ,setProduct] = useState<any>([]);
  const theme = useTheme();


  return (
    <Box
      display="flex"
      flexWrap="wrap"
      justifyContent="center"
      gap={2}
      p={2}
    >
      {products.map((product) => (
        <Box
          key={product.id}
          sx={{
            width: 'calc(33.333% - 16px)', // 3 columns with gap
            maxWidth: 200,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
          }}
        >
          <Box
            component="img"
            src={product.image}
            alt={product.name}
            sx={{
              width: '100%',
              height: 120,
              objectFit: 'cover',
              borderRadius: 2,
              boxShadow: 1,
            }}
          />
          <Typography
            variant="body2"
            mt={1}
            sx={{
              width: '100%',
              textAlign: 'center',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              fontWeight: 300,
            }}
          >
            {product.name}
          </Typography>
        </Box>
      ))}
    </Box>
  );
};

export default  ProductCatalog;
